from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.shortcuts import get_object_or_404
from .models import OrgStructureUnit

class MergeOrgUnitView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, source_unit_id):
        source_unit = get_object_or_404(
            OrgStructureUnit, id=source_unit_id, enterprise=request.user.enterprise
        )
        dest_unit_id = request.data.get("dest_unit_id")
        dest_unit = get_object_or_404(
            OrgStructureUnit, id=dest_unit_id, enterprise=request.user.enterprise
        )

        for child in source_unit.get_children():
            child.move_to(dest_unit, position="last-child")

        return Response({"status": "merged", "source": source_unit.id, "dest": dest_unit.id})
